import type { Pool } from 'pg';

import cors from '@fastify/cors';
import { HttpError } from 'api-shared';
import Fastify, {
  type FastifyInstance,
  type FastifyReply,
  type FastifyRequest,
} from 'fastify';

import type { EnvConfig } from '../config/env.schema';

import { createCarSalesPlugin } from '../features/carSales/carSales.plugin';
import { createDbSanityPlugin } from '../features/dbSanity/dbSanity.plugin';
import { createDistinctPlugin } from '../features/distinct/distinct.plugin';
import { createEnterpriseOrdersPlugin } from '../features/enterpriseOrders/enterpriseOrders.plugin';
import { createWideAlltypes150Plugin } from '../features/wideAlltypes150/wideAlltypes150.plugin';

type CreateAppArgs = {
  readonly envConfig: EnvConfig;
  readonly pool: Pool;
};

type RequestWithStartNs = FastifyRequest & {
  requestStartNs?: bigint;
};

const formatHumanTimestamp = () => {
  const now = new Date();
  const date = now.toLocaleDateString('sv-SE');
  const time = now.toLocaleTimeString('sv-SE', { hour12: false });
  const milliseconds = String(now.getMilliseconds()).padStart(3, '0');

  return `${date} ${time}.${milliseconds}`;
};

const getDurationMs = ({
  request,
}: {
  readonly request: RequestWithStartNs;
}) => {
  if (request.requestStartNs === undefined) {
    return 0;
  }

  const elapsedNs = process.hrtime.bigint() - request.requestStartNs;
  return Number(elapsedNs) / 1_000_000;
};

const logApiRequest = ({
  reply,
  request,
}: {
  readonly reply: FastifyReply;
  readonly request: RequestWithStartNs;
}) => {
  const timestamp = formatHumanTimestamp();
  const durationMs = getDurationMs({ request }).toFixed(1);
  const endpoint = request.url.split('?', 1)[0] ?? request.url;

  console.info(
    `[API][${timestamp}] ${request.method} ${endpoint} -> ${reply.statusCode} (${durationMs}ms)`,
  );
};

/**
 * Create the Fastify application with all API routes.
 */
export const createApp = ({
  envConfig,
  pool,
}: CreateAppArgs): FastifyInstance => {
  const app = Fastify({ logger: false });

  app.addHook('onRequest', (request, _reply, done) => {
    const requestWithStartNs = request as RequestWithStartNs;
    requestWithStartNs.requestStartNs = process.hrtime.bigint();
    done();
  });

  app.addHook('onResponse', (request, reply, done) => {
    logApiRequest({
      reply,
      request: request as RequestWithStartNs,
    });
    done();
  });

  app.register(cors);

  // --- Error handling ---------------------------------------------------

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof HttpError) {
      reply.status(error.statusCode).send({ error: error.message });
      return;
    }

    // Fastify validation errors (schema failures) carry a statusCode
    const statusCode =
      'statusCode' in (error as object) &&
      typeof (error as { statusCode?: unknown }).statusCode === 'number'
        ? (error as { statusCode: number }).statusCode
        : 500;

    if (statusCode < 500) {
      const message = error instanceof Error ? error.message : 'Bad request';
      reply.status(statusCode).send({ error: message });
      return;
    }

    console.error('❌ Unhandled API error:', error);
    reply.status(500).send({ error: 'Internal server error' });
  });

  app.setNotFoundHandler((_request, reply) => {
    reply.status(404).send({ error: 'Route not found' });
  });

  // --- Route plugins ----------------------------------------------------

  app.register(createCarSalesPlugin({ pool }), {
    prefix: '/api/car-sales',
  });
  app.register(createDistinctPlugin({ envConfig, pool }), {
    prefix: '/api/distinct',
  });
  app.register(createEnterpriseOrdersPlugin({ envConfig, pool }), {
    prefix: '/api/enterprise-orders',
  });
  app.register(createWideAlltypes150Plugin({ pool }), {
    prefix: '/api/wide-alltypes-150',
  });
  app.register(createDbSanityPlugin({ pool }), {
    prefix: '/api/db-sanity',
  });

  return app;
};

import type { EnvConfig } from './env.schema';

type ReadEnvConfigArgs = {
  readonly env: NodeJS.ProcessEnv;
};

const readEnvInteger = (
  value: string | undefined,
  fallback: number,
): number => {
  if (value === undefined || value === '') {
    return fallback;
  }

  const parsed = Number.parseInt(value, 10);
  return Number.isNaN(parsed) ? fallback : parsed;
};

const readEnvString = (value: string | undefined, fallback: string): string => {
  return value && value.length > 0 ? value : fallback;
};

/**
 * Parse and validate environment configuration for the API server.
 */
export const readEnvConfig = ({ env }: ReadEnvConfigArgs): EnvConfig => ({
  API_PORT: readEnvInteger(env.API_PORT, 3001),
  DB_HOST: readEnvString(env.DB_HOST, 'localhost'),
  DB_NAME: readEnvString(env.DB_NAME, 'car_sales_db'),
  DB_PASSWORD: readEnvString(env.DB_PASSWORD, 'root'),
  DB_PORT: readEnvInteger(env.DB_PORT, 5432),
  DB_USER: readEnvString(env.DB_USER, 'root'),
  DISTINCT_VALUES_DELAY_MS: readEnvInteger(
    env.DISTINCT_VALUES_DELAY_MS,
    10_000,
  ),
  ENTERPRISE_ORDERS_DELAY_MS: readEnvInteger(
    env.ENTERPRISE_ORDERS_DELAY_MS,
    3000,
  ),
});

import type { FastifyPluginAsync } from 'fastify';
import type { Pool } from 'pg';

import { createDbSanityRepository } from './dbSanity.repository';

type CreateDbSanityPluginArgs = {
  readonly pool: Pool;
};

/**
 * Fastify plugin for DB sanity endpoints.
 */
export const createDbSanityPlugin =
  ({ pool }: CreateDbSanityPluginArgs): FastifyPluginAsync =>
  async (fastify) => {
    const repository = createDbSanityRepository({ pool });

    fastify.get('/', async (_request, reply) => {
      const sanity = await repository.getDbSanity();
      reply.status(sanity.isHealthy ? 200 : 503);
      return sanity;
    });
  };

import type { FastifyPluginAsync } from 'fastify';
import type { Pool } from 'pg';

import { HttpError } from 'api-shared';

import type { EnvConfig } from '../../config/env.schema';

import { delay } from '../../utils/delay.util';
import { createJsonFieldsParser } from '../../utils/parseJsonQueryFields.util';
import { createEnterpriseOrdersRepository } from './enterpriseOrders.repository';
import {
  type OrderByIdParams,
  orderByIdParamsSchema,
  type PaginatedEnterpriseOrdersQuery,
  paginatedEnterpriseOrdersQuerySchema,
} from './enterpriseOrders.schema';

type CreateEnterpriseOrdersPluginArgs = {
  readonly envConfig: EnvConfig;
  readonly pool: Pool;
};

/**
 * Fastify plugin for enterprise-order endpoints.
 */
export const createEnterpriseOrdersPlugin =
  ({ envConfig, pool }: CreateEnterpriseOrdersPluginArgs): FastifyPluginAsync =>
  async (fastify) => {
    const repository = createEnterpriseOrdersRepository({ pool });

    fastify.addHook(
      'preValidation',
      createJsonFieldsParser(['sort', 'filter']),
    );

    fastify.get<{ Querystring: PaginatedEnterpriseOrdersQuery }>(
      '/paginated',
      { schema: { querystring: paginatedEnterpriseOrdersQuerySchema } },
      async (request) => {
        if (envConfig.ENTERPRISE_ORDERS_DELAY_MS > 0) {
          await delay({
            milliseconds: envConfig.ENTERPRISE_ORDERS_DELAY_MS,
          });
        }

        const { filter, limit, skip, sort } = request.query;

        return repository.getPaginated({
          filters: filter,
          limit,
          skip,
          sorting: sort,
        });
      },
    );

    fastify.get<{ Params: OrderByIdParams }>(
      '/:orderId',
      { schema: { params: orderByIdParamsSchema } },
      async (request) => {
        const orderId = Number.parseInt(request.params.orderId, 10);

        const result = await repository.getOrderById(orderId);

        if (!result) {
          throw new HttpError({
            message: 'Order not found',
            statusCode: 404,
          });
        }

        return result;
      },
    );
  };

import type { SortRule } from 'api-shared';

import {
  DEFAULT_PAGE_LIMIT,
  ENTERPRISE_ORDER_ALLOWED_COLUMNS,
} from 'api-shared';

import type { EnterpriseOrdersFilters } from './enterpriseOrders.types';

const filterValueSchema = {
  additionalProperties: false,
  allOf: [
    {
      if: {
        properties: {
          type: { const: 'boolean' },
        },
        required: ['type'],
      },
      // oxlint-disable-next-line unicorn/no-thenable -- JSON Schema uses then/if conditionals
      then: {
        properties: {
          value: { type: 'boolean' },
        },
        required: ['type', 'value'],
      },
    },
    {
      if: {
        properties: {
          type: { const: 'date' },
        },
        required: ['type'],
      },
      // oxlint-disable-next-line unicorn/no-thenable -- JSON Schema uses then/if conditionals
      then: {
        properties: {
          operator: {
            enum: ['after', 'before', 'between', 'equals'],
            type: 'string',
          },
          value: { minLength: 1, type: 'string' },
          value2: { minLength: 1, type: 'string' },
        },
        required: ['type', 'operator', 'value'],
      },
    },
    {
      if: {
        properties: {
          type: { const: 'number' },
        },
        required: ['type'],
      },
      // oxlint-disable-next-line unicorn/no-thenable -- JSON Schema uses then/if conditionals
      then: {
        properties: {
          operator: {
            enum: [
              'between',
              'equals',
              'greaterThan',
              'greaterThanOrEqual',
              'lessThan',
              'lessThanOrEqual',
              'notEquals',
            ],
            type: 'string',
          },
          value: { type: 'number' },
          value2: { type: 'number' },
        },
        required: ['type', 'operator', 'value'],
      },
    },
    {
      if: {
        properties: {
          type: { enum: ['multiSelect', 'select'] },
        },
        required: ['type'],
      },
      // oxlint-disable-next-line unicorn/no-thenable -- JSON Schema uses then/if conditionals
      then: {
        properties: {
          operator: { enum: ['equals', 'notEquals'], type: 'string' },
          value: { minLength: 1, type: 'string' },
          values: {
            items: { minLength: 1, type: 'string' },
            type: 'array',
          },
        },
      },
    },
    {
      if: {
        properties: {
          type: { const: 'text' },
        },
        required: ['type'],
      },
      // oxlint-disable-next-line unicorn/no-thenable -- JSON Schema uses then/if conditionals
      then: {
        properties: {
          operator: {
            enum: [
              'contains',
              'endsWith',
              'equals',
              'notContains',
              'notEquals',
              'startsWith',
            ],
            type: 'string',
          },
          value: { minLength: 1, type: 'string' },
        },
        required: ['type', 'operator', 'value'],
      },
    },
  ],
  properties: {
    operator: { type: 'string' },
    type: {
      enum: ['boolean', 'date', 'multiSelect', 'number', 'select', 'text'],
      type: 'string',
    },
    value: {},
    value2: {},
    values: {
      items: { minLength: 1, type: 'string' },
      type: 'array',
    },
  },
  required: ['type'],
  type: 'object',
};

// ---------------------------------------------------------------------------
// Sort rule sub-schema
// ---------------------------------------------------------------------------

const sortRuleSchema = {
  additionalProperties: false,
  properties: {
    columnKey: {
      enum: [...ENTERPRISE_ORDER_ALLOWED_COLUMNS],
      type: 'string',
    },
    direction: { enum: ['asc', 'desc'], type: 'string' },
  },
  required: ['columnKey', 'direction'],
  type: 'object',
};

// ---------------------------------------------------------------------------
// Route querystring schemas
// ---------------------------------------------------------------------------

/**
 * TypeScript type for the /paginated querystring.
 */
export type PaginatedEnterpriseOrdersQuery = {
  readonly filter: EnterpriseOrdersFilters;
  readonly limit: number;
  readonly skip: number;
  readonly sort: readonly SortRule[];
};

/**
 * JSON Schema for the /paginated querystring.
 */
export const paginatedEnterpriseOrdersQuerySchema = {
  properties: {
    filter: {
      additionalProperties: filterValueSchema,
      default: {},
      propertyNames: { enum: [...ENTERPRISE_ORDER_ALLOWED_COLUMNS] },
      type: 'object',
    },
    limit: { default: DEFAULT_PAGE_LIMIT, minimum: 1, type: 'integer' },
    skip: { default: 0, minimum: 0, type: 'integer' },
    sort: {
      default: [],
      items: sortRuleSchema,
      type: 'array',
    },
  },
  type: 'object',
};

/**
 * TypeScript type for the /:orderId params.
 */
export type OrderByIdParams = {
  readonly orderId: string;
};

/**
 * JSON Schema for the /:orderId params.
 */
export const orderByIdParamsSchema = {
  properties: {
    orderId: { pattern: String.raw`^\d+$`, type: 'string' },
  },
  required: ['orderId'],
  type: 'object',
};

import { runStartupDbSanityCheck } from 'api-shared';
import { Pool } from 'pg';

import { createApp } from './app/app';
import { readEnvConfig } from './config/env.util';
import { createDbSanityRepository } from './features/dbSanity/dbSanity.repository';

const envConfig = readEnvConfig({ env: process.env });

const pool = new Pool({
  database: envConfig.DB_NAME,
  host: envConfig.DB_HOST,
  password: envConfig.DB_PASSWORD,
  port: envConfig.DB_PORT,
  user: envConfig.DB_USER,
});

const app = createApp({ envConfig, pool });

const dbSanityRepository = createDbSanityRepository({ pool });

const start = async (): Promise<void> => {
  try {
    await app.listen({ host: '0.0.0.0', port: envConfig.API_PORT });
    console.warn(
      `🚀 API server (Fastify) running at http://localhost:${envConfig.API_PORT}`,
    );
    console.warn(
      `🛠️ Delays: enterpriseOrders=${envConfig.ENTERPRISE_ORDERS_DELAY_MS}ms, distinctValues=${envConfig.DISTINCT_VALUES_DELAY_MS}ms`,
    );
  } catch (error) {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  }
};

void start();
void runStartupDbSanityCheck({
  dbSanityRepository,
  repopulateCommand: '`vp run seed` in api-server',
});

const shutdown = async (): Promise<void> => {
  console.warn('🛑 Shutting down API server');
  await app.close();
  await pool.end();
};

process.on('SIGINT', () => {
  void shutdown().catch((error: unknown) => {
    console.error('❌ Error during SIGINT shutdown:', error);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';

import { delay } from './delay.util';

describe('delay', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it('resolves after the requested number of milliseconds', async () => {
    vi.useFakeTimers();

    let isResolved = false;
    const promise = delay({ milliseconds: 50 }).then(() => {
      isResolved = true;
    });

    await vi.advanceTimersByTimeAsync(49);
    expect(isResolved).toBe(false);

    await vi.advanceTimersByTimeAsync(1);
    await promise;

    expect(isResolved).toBe(true);
  });
});

import type { Pool } from 'pg';

import { HttpError } from 'api-shared';
import cors from 'cors';
import express, { type Express, Router } from 'express';

import type { EnvConfig } from '../config/env.schema';

import { createCarSalesRoute } from '../features/carSales/carSales.route';
import { createDbSanityRoute } from '../features/dbSanity/dbSanity.route';
import { createDistinctRoute } from '../features/distinct/distinct.route';
import { createEnterpriseOrdersRoute } from '../features/enterpriseOrders/enterpriseOrders.route';
import { createWideAlltypes150Route } from '../features/wideAlltypes150/wideAlltypes150.route';
import { errorMiddleware } from '../middleware/error.middleware';

type CreateAppArgs = {
  readonly envConfig: EnvConfig;
  readonly pool: Pool;
};

/**
 * Create the Express application with all API routes.
 */
export const createApp = ({ envConfig, pool }: CreateAppArgs): Express => {
  const app = express();
  const apiRouter = Router();
  const allowedCorsOrigins = new Set(
    envConfig.CORS_ALLOWED_ORIGINS.split(',')
      .map((origin) => origin.trim())
      .filter((origin) => origin.length > 0),
  );

  app.use(
    cors({
      origin: (origin, callback) => {
        callback(null, !origin || allowedCorsOrigins.has(origin));
      },
    }),
  );
  app.use(express.json());

  apiRouter.use('/car-sales', createCarSalesRoute({ pool }));
  apiRouter.use('/distinct', createDistinctRoute({ envConfig, pool }));
  apiRouter.use(
    '/enterprise-orders',
    createEnterpriseOrdersRoute({ envConfig, pool }),
  );
  apiRouter.use('/wide-alltypes-150', createWideAlltypes150Route({ pool }));
  apiRouter.use('/db-sanity', createDbSanityRoute({ pool }));

  app.use('/api', apiRouter);
  // eslint-disable-next-line local-rules/destructuring-for-functions
  app.use((_request, _response, next) => {
    next(new HttpError({ message: 'Route not found', statusCode: 404 }));
  });
  app.use(errorMiddleware);

  return app;
};

import { z } from 'zod';

type CreateEnvSchemaArgs = {
  readonly corsAllowedOriginsDefault: string;
};

const parseCorsAllowedOrigins = (origins: string): readonly string[] =>
  origins
    .split(',')
    .map((origin) => origin.trim())
    .filter((origin) => origin.length > 0);

const isLocalhostOrigin = (url: URL): boolean => {
  const normalizedHostname = url.hostname.toLowerCase();

  return (
    normalizedHostname === 'localhost' ||
    normalizedHostname === '127.0.0.1' ||
    normalizedHostname === '::1'
  );
};

const isAllowedOriginProtocol = (origin: string): boolean => {
  try {
    const parsedOrigin = new URL(origin);

    if (isLocalhostOrigin(parsedOrigin)) {
      return (
        parsedOrigin.protocol === 'http:' || parsedOrigin.protocol === 'https:'
      );
    }

    return parsedOrigin.protocol === 'https:';
  } catch {
    return false;
  }
};

export const createEnvSchema = ({
  corsAllowedOriginsDefault,
}: CreateEnvSchemaArgs) =>
  z.object({
    API_PORT: z.coerce.number().int().positive().default(3001),
    CORS_ALLOWED_ORIGINS: z
      .string()
      .default(corsAllowedOriginsDefault)
      .refine(
        (origins) =>
          parseCorsAllowedOrigins(origins).every(isAllowedOriginProtocol),
        {
          message:
            'CORS_ALLOWED_ORIGINS must contain absolute URLs separated by commas. Non-local origins must use https.',
        },
      ),
    DB_HOST: z.string().default('localhost'),
    DB_NAME: z.string().default('car_sales_db'),
    DB_PASSWORD: z.string().default('root'),
    DB_PORT: z.coerce.number().int().positive().default(5432),
    DB_USER: z.string().default('root'),
    DISTINCT_VALUES_DELAY_MS: z.coerce
      .number()
      .int()
      .nonnegative()
      .default(10_000),
    ENTERPRISE_ORDERS_DELAY_MS: z.coerce
      .number()
      .int()
      .nonnegative()
      .default(3000),
  });

export type EnvConfig = z.infer<ReturnType<typeof createEnvSchema>>;

import type { RequestHandler } from 'express';

import {
  DEFAULT_PAGE_LIMIT,
  ENTERPRISE_ORDER_ALLOWED_COLUMNS,
  HttpError,
} from 'api-shared';

import type { EnterpriseOrdersRepository } from './enterpriseOrders.repository';

import { createRequestHandler } from '../../utils/createRequestHandler.util';
import { delay } from '../../utils/delay.util';
import { readQueryInteger } from '../../utils/readQueryInteger.util';
import { readQueryValue } from '../../utils/readQueryValue.util';
import {
  parseEnterpriseOrdersFilters,
  parseEnterpriseOrdersSorting,
} from './enterpriseOrders.schema';

export type EnterpriseOrdersController = {
  readonly getOrderById: RequestHandler;
  readonly getPaginated: RequestHandler;
};

type CreateEnterpriseOrdersControllerArgs = {
  readonly enterpriseOrdersDelayMs: number;
  readonly repository: EnterpriseOrdersRepository;
};

/**
 * HTTP handlers for enterprise-order endpoints.
 */
export const createEnterpriseOrdersController = ({
  enterpriseOrdersDelayMs,
  repository,
}: CreateEnterpriseOrdersControllerArgs): EnterpriseOrdersController => ({
  getOrderById: createRequestHandler({
    handler: async ({ request, response }) => {
      const orderIdParam = readQueryValue(request.params.orderId);

      if (!orderIdParam) {
        throw new HttpError({ message: 'Missing order ID', statusCode: 400 });
      }

      const orderId = Number.parseInt(orderIdParam, 10);

      if (Number.isNaN(orderId)) {
        throw new HttpError({ message: 'Invalid order ID', statusCode: 400 });
      }

      const result = await repository.getOrderById(orderId);

      if (!result) {
        throw new HttpError({ message: 'Order not found', statusCode: 404 });
      }

      response.json(result);
    },
  }),
  getPaginated: createRequestHandler({
    handler: async ({ request, response }) => {
      if (enterpriseOrdersDelayMs > 0) {
        await delay({ milliseconds: enterpriseOrdersDelayMs });
      }

      const skip = readQueryInteger({
        fallback: 0,
        value: request.query.skip,
      });
      const limit = readQueryInteger({
        fallback: DEFAULT_PAGE_LIMIT,
        min: 1,
        value: request.query.limit,
      });
      const sorting = parseEnterpriseOrdersSorting({
        allowedColumns: ENTERPRISE_ORDER_ALLOWED_COLUMNS,
        value: request.query.sort,
      });
      const filters = parseEnterpriseOrdersFilters({
        allowedColumns: ENTERPRISE_ORDER_ALLOWED_COLUMNS,
        value: request.query.filter,
      });

      const result = await repository.getPaginated({
        filters,
        limit,
        skip,
        sorting,
      });

      response.json(result);
    },
  }),
});

import type { ErrorRequestHandler } from 'express';

import { HttpError } from 'api-shared';

// eslint-disable-next-line local-rules/destructuring-for-functions
export const errorMiddleware: ErrorRequestHandler = (
  error,
  _request,
  response,
  _next,
) => {
  if (error instanceof HttpError) {
    response.status(error.statusCode).json({ error: error.message });
    return;
  }

  console.error('❌ Unhandled API error:', error);
  response.status(500).json({ error: 'Internal server error' });
};

import type { NextFunction, Request, RequestHandler, Response } from 'express';

type CreateRequestHandlerArgs = {
  readonly handler: (args: RequestHandlerArgs) => Promise<void> | void;
};

type RequestHandlerArgs = {
  readonly next: NextFunction;
  readonly request: Request;
  readonly response: Response;
};

/**
 * Adapt object-argument handlers to Express request handlers.
 */
export const createRequestHandler =
  ({ handler }: CreateRequestHandlerArgs): RequestHandler =>
  // eslint-disable-next-line local-rules/destructuring-for-functions
  (request, response, next) => {
    Promise.resolve(handler({ next, request, response })).catch(next);
  };

import { afterEach, describe, expect, it, vi } from 'vitest';

import { delay } from './delay.util';

describe('delay', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it('resolves after the requested number of milliseconds', async () => {
    vi.useFakeTimers();

    let isResolved = false;
    const promise = delay({ milliseconds: 25 }).then(() => {
      isResolved = true;
    });

    await vi.advanceTimersByTimeAsync(24);
    expect(isResolved).toBe(false);

    await vi.advanceTimersByTimeAsync(1);
    await promise;

    expect(isResolved).toBe(true);
  });
});

import { readQueryValue } from './readQueryValue.util';

type ReadQueryIntegerArgs = {
  readonly fallback: number;
  readonly max?: number;
  readonly min?: number;
  readonly value: unknown;
};

/**
 * Parse an integer query param with fallback and clamp support.
 */
export const readQueryInteger = ({
  fallback,
  max,
  min = 0,
  value,
}: ReadQueryIntegerArgs): number => {
  const normalizedValue = readQueryValue(value);

  if (!normalizedValue) {
    return fallback;
  }

  const parsedValue = Number.parseInt(normalizedValue, 10);

  if (Number.isNaN(parsedValue)) {
    return fallback;
  }

  const boundedValue = Math.max(min, parsedValue);

  if (max === undefined) {
    return boundedValue;
  }

  return Math.min(boundedValue, max);
};

import type { Queryable, SortRule } from '../../types/api.types.js';
import type {
  CarSalesResponse,
  PaginatedCarSalesResponse,
} from './carSales.types.js';

import { buildOrderByClause } from '../../utils/buildOrderByClause.util.js';
import { DEFAULT_CAR_SALES_SORTING } from './carSales.constants.js';

export type CarSalesRepository = {
  readonly getAll: () => Promise<CarSalesResponse>;
  readonly getPaginated: (
    args: GetPaginatedCarSalesArgs,
  ) => Promise<PaginatedCarSalesResponse>;
};

type CreateCarSalesRepositoryArgs = {
  readonly pool: Queryable;
};

type GetPaginatedCarSalesArgs = {
  readonly limit: number;
  readonly skip: number;
  readonly sorting: readonly SortRule[];
};

/**
 * Database access for car sales endpoints.
 */
