      compilerOptions: createAppCompilerOptions({
        paths,
        rootDirs,
        tsBuildInfoFile,
        types,
      }),
      exclude: APP_TS_CONFIG.exclude,
      include: APP_TS_CONFIG.include,
    },
    {
      exclude,
      include,
    },
  );

